#!/usr/bin/env node
// TBO Copilot branding.
//
// Re-applies every user-visible rename from PI-Desktop to TBO Copilot. Run it
// after each merge of an upstream PI-Desktop release (docs/tbo/upstream-sync.md).
//
//   node scripts/tbo/apply-branding.mjs          apply the branding
//   node scripts/tbo/apply-branding.mjs --check  exit 1 if anything is unbranded
//
// Only user-facing names change. Internal identifiers stay upstream's so merges
// stay small: package names (@pi-desktop/*), the host-core binary, the
// PI_DESKTOP_DATA_DIR variable, file markers such as "Generated by PI-Desktop",
// and model-facing prompts.
//
// Each rule says what to find and what to put instead. A rule whose `find` is
// gone but whose `done` text is present is already applied. A rule where neither
// is present means upstream changed that place: the script reports it so a person
// can update the rule.
//
// Brand images (icons, installer background, renderer marks) live in
// scripts/tbo/assets/, laid out like the repository, and are copied over
// upstream's files. scripts/tbo/make-brand-assets.py regenerates them.

import { copyFileSync, existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const ASSETS = join(ROOT, "scripts", "tbo", "assets");

export const BRAND = {
  name: "TBO Copilot",
  appId: "com.teambackoffice.copilot",
  artifactPrefix: "TBO-Copilot",
  packageName: "tbo-copilot",
  dataDir: ".tbo-copilot",
  devDataDir: ".tbo-copilot-dev",
  repo: "tbocloud/tbo-copilot",
};

const LOCALES = ["en", "de", "es", "fr", "ko", "pt-BR", "tr", "zh-CN", "zh-TW"];

const rule = (file, find, replace, options = {}) => ({ file, find, replace, ...options });

const RULES = [
  // Packaging (electron-builder) and package metadata.
  rule("apps/desktop/package.json", '"description": "PI-Desktop Electron application"', `"description": "${BRAND.name} Electron application"`),
  rule("apps/desktop/package.json", '"homepage": "https://github.com/vastsa/PI-Desktop"', `"homepage": "https://github.com/${BRAND.repo}"`),
  rule("apps/desktop/package.json", '"appId": "net.aiuo.pi-desktop"', `"appId": "${BRAND.appId}"`),
  rule("apps/desktop/package.json", '"productName": "PI-Desktop"', `"productName": "${BRAND.name}"`),
  rule(
    "apps/desktop/package.json",
    /"owner": "vastsa",(\s*)"repo": "PI-Desktop"/,
    `"owner": "${BRAND.repo.split("/")[0]}",$1"repo": "${BRAND.repo.split("/")[1]}"`,
    { done: `"repo": "${BRAND.repo.split("/")[1]}"` },
  ),
  rule("apps/desktop/package.json", '"PI-Desktop-', `"${BRAND.artifactPrefix}-`, { all: true }),
  rule("apps/desktop/package.json", '"executableName": "PI-Desktop"', `"executableName": "${BRAND.name}"`),
  rule("apps/desktop/package.json", '"shortcutName": "PI-Desktop"', `"shortcutName": "${BRAND.name}"`),
  rule("apps/desktop/package.json", '"packageName": "pi-desktop"', `"packageName": "${BRAND.packageName}"`, { all: true }),
  rule("apps/desktop/package.json", '"pi-desktop_${', `"${BRAND.packageName}_\${`),
  rule("apps/desktop/package.json", '"pi-desktop-${', `"${BRAND.packageName}-\${`),
  rule("apps/desktop/package.json", '"executableName": "pi-desktop"', `"executableName": "${BRAND.packageName}"`),
  rule(
    "apps/desktop/package.json",
    /("NS\w+UsageDescription": "[^"]*)PI-Desktop/,
    `$1${BRAND.name}`,
    { all: true, done: `UsageDescription": "${BRAND.name}` },
  ),

  // Identity used by the main process (app name, userData, menu, tray, about).
  rule("packages/shared/src/protocol.ts", 'export const APP_ID = "net.aiuo.pi-desktop";', `export const APP_ID = "${BRAND.appId}";`),
  rule("packages/shared/src/protocol.ts", 'export const APP_NAME = "PI-Desktop";', `export const APP_NAME = "${BRAND.name}";`),
  rule("scripts/dev-electron.mjs", 'const APP_NAME = "PI-Desktop";', `const APP_NAME = "${BRAND.name}";`),
  rule("scripts/dev-electron.mjs", 'const DEV_BUNDLE_ID = "net.aiuo.pi-desktop.dev";', `const DEV_BUNDLE_ID = "${BRAND.appId}.dev";`),

  // Own data folders, so TBO Copilot never shares a database with PI-Desktop.
  rule("apps/desktop/electron/main/data-paths.ts", 'INSTALLATION_DATA_DIR_NAME = ".pi-desktop";', `INSTALLATION_DATA_DIR_NAME = "${BRAND.dataDir}";`),
  rule("apps/desktop/electron/main/data-paths.ts", 'DEVELOPMENT_DATA_DIR_NAME = ".pi-desktop-dev";', `DEVELOPMENT_DATA_DIR_NAME = "${BRAND.devDataDir}";`),

  // Release page link.
  rule(
    "apps/desktop/electron/main/updater.ts",
    '"https://github.com/vastsa/PI-Desktop/releases/latest"',
    `"https://github.com/${BRAND.repo}/releases/latest"`,
  ),

  // Window and renderer text.
  rule("apps/desktop/index.html", "<title>PI-Desktop</title>", `<title>${BRAND.name}</title>`),
  rule("apps/desktop/src/features/settings/SettingsPage.tsx", '|| "PI-Desktop"', `|| "${BRAND.name}"`),
  rule("apps/desktop/src/lib/startup-watchdog.ts", '"PI-Desktop startup diagnostics"', `"${BRAND.name} startup diagnostics"`),
  rule("apps/desktop/src/components/settings/ProviderHeadersEditor.tsx", 'value: "PI-Desktop"', `value: "${BRAND.name}"`, { all: true }),

  // Main-process messages people see.
  rule("apps/desktop/electron/main/live-voice/widget-window.ts", '"PI-Desktop Live Voice"', `"${BRAND.name} Live Voice"`),
  rule("apps/desktop/electron/main/mcp-oauth.ts", "return to PI-Desktop.", `return to ${BRAND.name}.`),
  rule("apps/desktop/electron/main/mcp-oauth.ts", 'clientName = "PI-Desktop"', `clientName = "${BRAND.name}"`),
  rule("apps/desktop/electron/main/mcp-oauth.ts", 'clientInfo: { name: "PI-Desktop"', `clientInfo: { name: "${BRAND.name}"`),
  rule("apps/desktop/electron/main/plugin-mcp.ts", 'clientInfo: { name: "PI-Desktop"', `clientInfo: { name: "${BRAND.name}"`),
  rule("apps/desktop/electron/main/storage/bootstrap.ts", "before starting PI-Desktop.", `before starting ${BRAND.name}.`),
  rule("apps/desktop/electron/main/plugin-shortcut-registry.ts", "is already used by PI-Desktop", `is already used by ${BRAND.name}`),
  rule("apps/desktop/electron/main/host-boot-diagnostics.ts", "Install the newer PI-Desktop that", `Install the newer ${BRAND.name} that`),
  rule("apps/desktop/electron/main/ipc/session-ipc.ts", 'cannot be deleted from PI-Desktop"', `cannot be deleted from ${BRAND.name}"`),

  // Every translated string.
  ...LOCALES.map((locale) =>
    rule(`packages/i18n/src/locales/${locale}/index.ts`, "PI-Desktop", BRAND.name, { all: true }),
  ),

  // Upstream tests that pin the product identity expect the TBO values.
  ...testRules("apps/desktop/test/startup-watchdog.test.mjs", [
    [String.raw`/^PI-Desktop startup diagnostics\n/`, String.raw`/^TBO Copilot startup diagnostics\n/`],
    [`/stalledTitle: "PI-Desktop couldn't finish starting"/`, `/stalledTitle: "TBO Copilot couldn't finish starting"/`],
    [`/stalledTitle: "PI-Desktop 未能完成启动"/`, `/stalledTitle: "TBO Copilot 未能完成启动"/`],
  ]),
  ...testRules("apps/desktop/test/development-branding.test.mjs", [
    ['build.win.executableName, "PI-Desktop")', 'build.win.executableName, "TBO Copilot")'],
    ['build.nsis.shortcutName, "PI-Desktop")', 'build.nsis.shortcutName, "TBO Copilot")'],
    [String.raw`/<string>PI-Desktop<\/string>/`, String.raw`/<string>TBO Copilot<\/string>/`],
    [String.raw`/<string>net\.aiuo\.pi-desktop\.dev<\/string>/`, String.raw`/<string>com\.teambackoffice\.copilot\.dev<\/string>/`],
  ]),
  ...testRules("apps/desktop/test/ci-workflow.test.mjs", [
    ['build.deb.artifactName, "pi-desktop_${version}_${arch}.${ext}")', 'build.deb.artifactName, "tbo-copilot_${version}_${arch}.${ext}")'],
    ['build.rpm.artifactName, "pi-desktop-${version}-${arch}.${ext}")', 'build.rpm.artifactName, "tbo-copilot-${version}-${arch}.${ext}")'],
    ['"PI-Desktop-${version}-${arch}-mac.${ext}",', '"TBO-Copilot-${version}-${arch}-mac.${ext}",'],
    ['"PI-Desktop-${version}-${arch}.${ext}",', '"TBO-Copilot-${version}-${arch}.${ext}",'],
  ]),
  ...testRules("apps/desktop/test/development-profile.test.mjs", [
    ['INSTALLATION_DATA_DIR_NAME, ".pi-desktop")', 'INSTALLATION_DATA_DIR_NAME, ".tbo-copilot")'],
    ['DEVELOPMENT_DATA_DIR_NAME, ".pi-desktop-dev")', 'DEVELOPMENT_DATA_DIR_NAME, ".tbo-copilot-dev")'],
    ['DEVELOPMENT_INSTALLATION_NAME, "PI-Desktop Dev")', 'DEVELOPMENT_INSTALLATION_NAME, "TBO Copilot Dev")'],
  ]),
  ...testRules("apps/desktop/test/auto-update.test.mjs", [
    [String.raw`/github\.com\/vastsa\/PI-Desktop\/releases/`, String.raw`/github\.com\/tbocloud\/tbo-copilot\/releases/`],
    ['publish[0].owner, "vastsa")', 'publish[0].owner, "tbocloud")'],
    ['publish[0].repo, "PI-Desktop")', 'publish[0].repo, "tbo-copilot")'],
    ['build.linux.executableName, "pi-desktop")', 'build.linux.executableName, "tbo-copilot")'],
    ['build.deb.packageName, "pi-desktop")', 'build.deb.packageName, "tbo-copilot")'],
    ['build.rpm.packageName, "pi-desktop")', 'build.rpm.packageName, "tbo-copilot")'],
    ['"pi-desktop-${version}-${arch}.${ext}",', '"tbo-copilot-${version}-${arch}.${ext}",'],
    ['"PI-Desktop-Setup-${version}.${ext}"', '"TBO-Copilot-Setup-${version}.${ext}"'],
    ['"PI-Desktop-Portable-${version}.${ext}"', '"TBO-Copilot-Portable-${version}.${ext}"', { all: true }],
  ]),
  ...testRules("apps/desktop/test/single-instance.test.mjs", [
    ['.endsWith("PI-Desktop Dev")', '.endsWith("TBO Copilot Dev")'],
    ['.endsWith(".pi-desktop-dev")', '.endsWith(".tbo-copilot-dev")'],
  ]),
  ...testRules("apps/desktop/test/renderer-branding.test.mjs", [
    [String.raw`/shellName:\s*"PI-Desktop"/`, String.raw`/shellName:\s*"TBO Copilot"/`, { all: true }],
    [String.raw`/placeholder:\s*"Ask PI-Desktop to help with anything"/`, String.raw`/placeholder:\s*"Ask TBO Copilot to help with anything"/`],
    [String.raw`/placeholder:\s*"让 PI-Desktop 帮你做任何事"/`, String.raw`/placeholder:\s*"让 TBO Copilot 帮你做任何事"/`],
  ]),
];

function testRules(file, pairs) {
  return pairs.map(([find, replace, options]) => rule(file, find, replace, options));
}

function applyRule(text, r) {
  if (typeof r.find === "string") {
    if (!text.includes(r.find)) return { text, changed: 0 };
    if (r.all) {
      const parts = text.split(r.find);
      return { text: parts.join(r.replace), changed: parts.length - 1 };
    }
    return { text: text.replace(r.find, () => r.replace), changed: 1 };
  }
  const flags = r.all ? (r.find.flags.includes("g") ? r.find.flags : `${r.find.flags}g`) : r.find.flags;
  const pattern = new RegExp(r.find.source, flags);
  const matches = text.match(pattern);
  if (!matches) return { text, changed: 0 };
  // A global regex keeps matching while a later match still exists (one
  // description can name the app twice), so repeat until stable.
  let next = text;
  let changed = 0;
  for (;;) {
    const before = next;
    next = next.replace(pattern, r.replace);
    if (next === before) break;
    changed += 1;
  }
  return { text: next, changed };
}

// Dot-files (the assets' own .gitignore) are not brand images.
function assetFiles(dir = ASSETS) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    if (entry.name.startsWith(".")) return [];
    const path = join(dir, entry.name);
    return entry.isDirectory() ? assetFiles(path) : [path];
  });
}

// Copies each brand image over the upstream file it replaces. A target that no
// longer exists is reported as stale rather than created: upstream moved or
// renamed it, and a person decides where the image belongs now.
function syncAssets(check, unbranded, stale) {
  let copied = 0;
  for (const source of assetFiles()) {
    const target = relative(ASSETS, source);
    const destination = join(ROOT, target);
    if (!existsSync(destination)) {
      stale.push(`${target}: brand image target not found`);
      continue;
    }
    if (readFileSync(source).equals(readFileSync(destination))) continue;
    if (check) unbranded.push(`${target}: differs from scripts/tbo/assets`);
    else {
      copyFileSync(source, destination);
      copied += 1;
    }
  }
  return copied;
}

function main() {
  const check = process.argv.includes("--check");
  const files = new Map();
  const read = (file) => {
    if (!files.has(file)) files.set(file, readFileSync(join(ROOT, file), "utf8"));
    return files.get(file);
  };

  let applied = 0;
  const unbranded = [];
  const stale = [];

  for (const r of RULES) {
    let text;
    try {
      text = read(r.file);
    } catch {
      stale.push(`${r.file}: file not found`);
      continue;
    }
    const done = r.done ?? r.replace;
    const result = applyRule(text, r);
    if (result.changed > 0) {
      if (check) unbranded.push(`${r.file}: ${String(r.find)}`);
      else {
        files.set(r.file, result.text);
        applied += result.changed;
      }
    } else if (!text.includes(done)) {
      stale.push(`${r.file}: neither ${JSON.stringify(String(r.find))} nor ${JSON.stringify(done)} found`);
    }
  }

  const copied = syncAssets(check, unbranded, stale);

  if (!check) {
    for (const [file, text] of files) writeFileSync(join(ROOT, file), text);
    console.log(`TBO branding: ${applied} replacement(s) applied, ${copied} brand image(s) copied.`);
  }
  for (const line of stale) console.warn(`  stale rule (upstream changed this place): ${line}`);
  if (check) {
    for (const line of unbranded) console.error(`  not branded: ${line}`);
    if (unbranded.length || stale.length) process.exit(1);
    console.log("TBO branding: everything is branded.");
  } else if (stale.length) {
    process.exitCode = 1;
  }
}

main();
